function localize(q:(typeof ENGLISH)[number],i:number,locale:PolLocaleV1):PolLocalizedQuestionV1{
 if(locale==="en")return {...q,chapterId:"POL-001",cpId:"POL-CP-014",qlName:q.qlId,reviewOnly:true,runtimeRegistered:false,options:[...q.options],locale,localizationV1:{version:POL_LOCALIZATION_V1,englishQuestionId:q.questionId,semanticInvariant:true,cpInvariant:true,qlInvariant:true,difficultyInvariant:true,sourceInvariant:true,optionOrderInvariant:true,correctIndexInvariant:true,reviewOnly:true}};
 let stem=STEMS[i]![locale],explanation=EXPS[i]![locale],options=q.options.map(x=>fallbackOption(x,locale));
 if(locale==="pa"){stem=applyPolityPunjabiNativePassV1(stem);explanation=applyPolityPunjabiNativePassV1(explanation);options=options.map(applyPolityPunjabiNativePassV1);}
 return {...q,chapterId:"POL-001",cpId:"POL-CP-014",qlName:q.qlId,reviewOnly:true,runtimeRegistered:false,questionId:q.questionId+"-"+locale.toUpperCase(),stem,options,canonicalAnswer:options[q.correctIndex]!,explanation,locale,localizationV1:{version:POL_LOCALIZATION_V1,englishQuestionId:q.questionId,semanticInvariant:true,cpInvariant:true,qlInvariant:true,difficultyInvariant:true,sourceInvariant:true,optionOrderInvariant:true,correctIndexInvariant:true,reviewOnly:true}};
}
